import{_ as i,c as s,o as t,a3 as o}from"./chunks/framework.CoV49S2T.js";const m=JSON.parse('{"title":"Politique de confidentialité","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/privacy.md","filePath":"fr/guide/privacy.md","lastUpdated":1787284674000}'),n={name:"fr/guide/privacy.md"};function a(l,e,r,u,c,p){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="politique-de-confidentialite" tabindex="-1">Politique de confidentialité <a class="header-anchor" href="#politique-de-confidentialite" aria-label="Permalink to &quot;Politique de confidentialité&quot;">​</a></h1><p>ClipboxAI est un gestionnaire de presse-papiers intelligent pour macOS. Votre confidentialité est notre priorité.</p><h2 id="conception-locale-d-abord" tabindex="-1">Conception locale d&#39;abord <a class="header-anchor" href="#conception-locale-d-abord" aria-label="Permalink to &quot;Conception locale d&#39;abord&quot;">​</a></h2><ul><li>Votre historique de presse-papiers est stocké entièrement sur votre Mac.</li><li>Les actions locales intégrées (extraire les liens, compter les statistiques, réduire les lignes vides, et les suggestions ML sur appareil) s&#39;exécutent entièrement hors ligne.</li><li>Aucun compte ni inscription n&#39;est requis pour utiliser l&#39;application principale.</li><li>Aucune connexion Internet n&#39;est requise pour la gestion locale du presse-papiers et les fonctionnalités sur appareil.</li></ul><h2 id="ia-cloud-facultatif" tabindex="-1">IA cloud (facultatif) <a class="header-anchor" href="#ia-cloud-facultatif" aria-label="Permalink to &quot;IA cloud (facultatif)&quot;">​</a></h2><p>ClipboxAI peut utiliser optionnellement des fournisseurs d&#39;IA cloud (tels que DeepSeek, MiniMax, GLM, Kimi, Mistral, ou un serveur Ollama local) pour alimenter des actions avancées comme le résumé, la traduction et les invites personnalisées.</p><ul><li>Lorsqu&#39;elle est activée, le texte sélectionné ou le contenu du presse-papiers est envoyé <strong>directement au fournisseur que vous configurez</strong>, en utilisant <strong>votre propre clé API</strong>.</li><li>Votre clé API est stockée uniquement dans le Keychain de votre Mac et n&#39;est jamais téléversée vers nous.</li><li>Vous pouvez désactiver l&#39;IA cloud à tout moment et continuer à utiliser les fonctionnalités locales.</li><li>L&#39;historique du presse-papiers n&#39;est <strong>pas</strong> envoyé vers le cloud automatiquement ; les requêtes cloud ne sont déclenchées que lorsque vous exécutez une action cloud.</li></ul><h2 id="ce-que-nous-ne-collectons-pas" tabindex="-1">Ce que nous ne collectons pas <a class="header-anchor" href="#ce-que-nous-ne-collectons-pas" aria-label="Permalink to &quot;Ce que nous ne collectons pas&quot;">​</a></h2><ul><li>Nous ne collectons pas le contenu de votre presse-papiers, vos documents ou vos fichiers.</li><li>Nous ne suivons pas votre activité, votre comportement de navigation ou vos habitudes d&#39;utilisation.</li><li>Nous n&#39;exploitons aucun serveur qui reçoit vos données de presse-papiers.</li><li>Nous n&#39;incluons aucune analytique, publicité ou SDK de suivi tiers.</li><li>Nous n&#39;avons aucun système de télémétrie.</li></ul><h2 id="quelles-donnees-sont-stockees-localement" tabindex="-1">Quelles données sont stockées localement <a class="header-anchor" href="#quelles-donnees-sont-stockees-localement" aria-label="Permalink to &quot;Quelles données sont stockées localement&quot;">​</a></h2><p>Les données suivantes sont stockées uniquement sur votre appareil :</p><ul><li><strong>Historique du presse-papiers</strong> : éléments récents pour un accès rapide (conservés sur votre Mac).</li><li><strong>Réglages de l&#39;application</strong> : thème, préférence de langue, actions activées, configuration du fournisseur.</li><li><strong>Clés API</strong> : stockées en toute sécurité dans le Keychain local (uniquement si vous configurez un fournisseur cloud).</li><li><strong>Actions personnalisées</strong> : invites et configuration que vous créez.</li><li><strong>Journaux</strong> : journaux de débogage pour le dépannage (peuvent être supprimés à tout moment).</li></ul><h2 id="permissions-utilisees-par-l-application" tabindex="-1">Permissions utilisées par l&#39;application <a class="header-anchor" href="#permissions-utilisees-par-l-application" aria-label="Permalink to &quot;Permissions utilisées par l&#39;application&quot;">​</a></h2><ul><li><strong>Accessibilité / Accès au disque complet</strong> : requis pour lire le presse-papiers système et fournir des raccourcis globaux.</li><li><strong>Notifications</strong> : facultatif, pour les alertes de fin sur les longues requêtes cloud.</li></ul><p>Vous pouvez gérer ces permissions dans <strong>Réglages système → Confidentialité et sécurité</strong> à tout moment.</p><h2 id="achats-integres-licence" tabindex="-1">Achats intégrés / Licence <a class="header-anchor" href="#achats-integres-licence" aria-label="Permalink to &quot;Achats intégrés / Licence&quot;">​</a></h2><p>Les achats de licence (le cas échéant) sont traités par Apple via le Mac App Store. ClipboxAI ne reçoit ni ne stocke vos informations de paiement. Les reçus de licence sont stockés localement pour vérifier la propriété.</p><h2 id="services-tiers" tabindex="-1">Services tiers <a class="header-anchor" href="#services-tiers" aria-label="Permalink to &quot;Services tiers&quot;">​</a></h2><p>ClipboxAI n&#39;inclut en soi aucune analytique, publicité ou service de suivi tiers. Lorsque vous activez un fournisseur d&#39;IA cloud, vos requêtes sont traitées par ce fournisseur selon sa propre politique de confidentialité.</p><h2 id="demandes-relatives-a-la-confidentialite" tabindex="-1">Demandes relatives à la confidentialité <a class="header-anchor" href="#demandes-relatives-a-la-confidentialite" aria-label="Permalink to &quot;Demandes relatives à la confidentialité&quot;">​</a></h2><p>Étant donné que ClipboxAI stocke toutes les données localement sur votre appareil, nous ne détenons aucune donnée personnelle sur nos serveurs. Si vous avez des questions sur la confidentialité, contactez-nous.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>Pour toute question sur la confidentialité, ouvrez un ticket sur <a href="https://github.com/clipboxAI/clipboard-site/issues" target="_blank" rel="noreferrer">GitHub Issues</a> ou envoyez-nous un e-mail à <a href="mailto:clipboxai@w3cub.com" target="_blank" rel="noreferrer">clipboxai@w3cub.com</a>.</p>',23)])])}const h=i(n,[["render",a]]);export{m as __pageData,h as default};
